// Generated by Cypress Author, 2026-10-13. Critical journeys use the database-free exercise demo.
const start=()=>{
 cy.setCookie('english.uiLocale','en');
 cy.visit('/exercise-demo',{onBeforeLoad(win){win.localStorage.clear();}});
 cy.contains('button','Start practice').click();
 cy.get('[data-cy="exercise"]').should('be.visible');
};
const check=()=>cy.get('[data-cy="check"]').click();
const correct=()=>cy.get('[data-cy="feedback"]').should('contain.text','Correct');
const next=()=>cy.get('[data-cy="next"]').click();
const order=(tokens:string[])=>{
 cy.contains('[data-cy="order-token"]',tokens[0]!).should('be.visible');
 // The move buttons are also the accessible touch/keyboard fallback to dragging.
 tokens.forEach((text,index)=>{
  const move=()=>cy.get('[data-cy="order-token"]').then(rows=>{
   const position=Array.from(rows).findIndex(row=>row.querySelector('span')?.textContent===text);
   expect(position,'token is present').to.be.at.least(index);
   if(position>index){cy.wrap(rows[position]).find('[data-cy="move-up"]').click();move();}
  });move();
 });
};
describe('Learning practice',()=>{
 it('answers all six exercise types → awards points and shows completion',()=>{
  start();cy.contains('button','because').click();check();correct();next();
  cy.contains('[data-cy="choice"]','Because I was tired, I went to bed early.').click();check();correct();next();
  cy.contains('button','True').click();check();correct();next();
  order(['I','studied','hard','so','I could pass.']);check();correct();next();
  order(['She','woke','up','early','because of the noise.']);check();correct();next();
  [['go','went'],['eat','ate'],['see','saw']].forEach(([left,right])=>{cy.contains('[data-cy="match-left"]',left!).click();cy.contains('[data-cy="match-right"]',right!).click();});
  check();correct();next();
  cy.get('dialog[open]').should('contain.text','6').and('contain.text','Points');
  cy.window().then(win=>{const p=JSON.parse(win.localStorage.getItem('english.progress.__demo__')!);expect(p.completed).to.equal(6);expect(p.session.finished).to.equal(true);expect(p.session.results).to.have.length(6);});
 });
 it('reloads and switches UI language → keeps position, draft and points without duplication',()=>{
  start();cy.contains('button','because').click();check();correct();
  cy.window().then(win=>{const before=win.localStorage.getItem('english.points.total');cy.reload();cy.get('[data-cy="feedback"]').should('contain.text','Correct');cy.window().its('localStorage').invoke('getItem','english.points.total').should('equal',before);});
  next();cy.contains('[data-cy="choice"]','Because I was tired, I went to bed early.').click();
  cy.get('[data-ui-locale-select]').select('es');
  cy.get('[data-cy="choice"][aria-pressed="true"]').should('contain.text','Because I was tired');check();cy.get('[data-cy="feedback"]').should('contain.text','Correcta');
 });
 it('submits a wrong answer then retries → breaks streak and retains unique completion',()=>{
  start();cy.contains('button','although').click();check();cy.get('[data-cy="feedback"]').should('contain.text','Incorrect');
  cy.get('[data-cy="retry"]').click();cy.contains('button','because').click();check();correct();
  cy.window().then(win=>{const p=JSON.parse(win.localStorage.getItem('english.progress.__demo__')!);expect(p.completed).to.equal(1);expect(Object.values(p.attempts)).to.deep.equal([2]);const points=JSON.parse(win.localStorage.getItem('english.points.__demo__')!);expect(points.streak).to.equal(1);});
 });
 it('uses a narrow viewport → actions remain reachable and shuffle keeps progress',()=>{
  cy.viewport(360,740);start();cy.contains('button','because').click();check();correct();next();
  cy.get('[data-cy="shuffle"]').click();cy.window().then(win=>{const p=JSON.parse(win.localStorage.getItem('english.progress.__demo__')!);expect(p.completed).to.equal(1);expect(p.session.results).to.have.length(1);});
  cy.document().then(doc=>expect(doc.documentElement.scrollWidth).to.be.at.most(360));
 });
});
